      ('الأشكال','مربع ومثلث ودائرة ومستطيل ومنحرف وشبه منحرف',Icons.category_rounded,Color(0xFFE94F9B)),
      ('الألعاب','لعبة حروف ولعبة أرقام',Icons.sports_esports_rounded,Color(0xFFFFB300)),
