class _ShapePainter extends CustomPainter{final int type;_ShapePainter(this.type);@override void paint(Canvas c,Size s){final p=Paint()..color=Colors.primaries[type%Colors.primaries.length].withValues(alpha:.85);final cx=s.width/2,cy=s.height/2,r=s.shortestSide*.28;final path=Path();if(type==0)c.drawRect(Rect.fromCenter(center:Offset(cx,cy),width:r*1.7,height:r*1.7),p);else if(type==1){path.moveTo(cx,cy-r);path.lineTo(cx-r,cy+r);path.lineTo(cx+r,cy+r);path.close();c.drawPath(path,p);}else if(type==2)c.drawCircle(Offset(cx,cy),r,p);else if(type==3)c.drawRect(Rect.fromCenter(center:Offset(cx,cy),width:r*2.1,height:r*1.35),p);else{final sides=type==4?4:type==5?4:type==6?5:type==7?6:type==8?8: type==9?0:4;if(type==9){c.drawOval(Rect.fromCenter(center:Offset(cx,cy),width:r*2.2,height:r*1.35),p);return;}for(int i=0;i<sides;i++){final a=-3.14159/2+i*2*3.14159/sides;final q=Offset(cx+r*cos(a),cy+r*sin(a));if(i==0)path.moveTo(q.dx,q.dy);else path.lineTo(q.dx,q.dy);}path.close();c.drawPath(path,p);}}@override bool shouldRepaint(covariant _ShapePainter old)=>old.type!=type;}
